<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { ref } from 'vue';
import RunFactsView from '@/components/RunFacts.vue';
import { useAuditedRequest } from '@/composables/useAuditedRequest';
import { dateUTC } from '@/types/leaderboard';
import type { Decision, RunFacts } from '@/types/leaderboard';
const props = defineProps<{ run: RunFacts; server_run_id: string; owner_id: number; review_version: number; evidence: Record<string, unknown> | null; record: Record<string, unknown> | null; initial_receipt: Record<string, unknown> | null; reward_receipt: Record<string, unknown> | null; decisions: Decision[] }>();
const reason = ref(''), decision = ref('approve');
const { ready, busy, error, pending, submit } = useAuditedRequest<{ decision: string; expected_version: number; reason: string }>(`pixel-review:${props.server_run_id}`);
async function decide() { if (await submit(`/api/v1/operations/runs/${props.server_run_id}/review`, { decision: decision.value, expected_version: props.review_version, reason: reason.value })) router.reload(); }
</script>
<template><Head title="Run Review" /><section class="site-section leaderboard-page operations-page"><Link href="/operations" class="quiet-link">← Operations</Link><h1>Run Review</h1><Link :href="`/operations/users/${owner_id}`" class="quiet-link">Player profile, Character Progress and logs →</Link><RunFactsView :run="run" /><h2>Evidence and checks</h2><pre data-testid="review-evidence">{{ JSON.stringify(evidence, null, 2) }}</pre><form v-if="['pending_review', 'accepted'].includes(run.status)" class="review-form" @submit.prevent="decide"><h2>Decision · version {{ review_version }}</h2><p>Approval repeats server validation and grants eligible rewards once. Hard contradictions cannot be overridden. Reviewing your own run is prohibited.</p><label for="review-decision">Action</label><select id="review-decision" v-model="decision" :disabled="busy || !!pending"><option value="approve">Accept</option><option v-if="run.status === 'accepted'" value="hold">Send for review</option><option value="reject">Reject</option></select><label for="review-reason">Decision reason</label><textarea id="review-reason" v-model="reason" minlength="8" maxlength="500" required :disabled="busy || !!pending" /><p v-if="pending" class="notice">Unfinished request: {{ pending.decision }}. Retrying preserves the original reason, version and ID.</p><p v-if="error" class="field-error" role="alert">{{ error }}</p><button class="site-button" :disabled="!ready || busy">{{ busy ? 'Saving…' : pending ? 'Retry decision' : 'Record decision' }}</button></form><p v-else class="notice">This status cannot be changed manually. Rewards and financial records are not deleted.</p><h2>Decision history</h2><ul class="review-history"><li v-for="(entry, index) in decisions" :key="index"><strong>{{ entry.action }}</strong> · {{ dateUTC(entry.created_at) }}<p>{{ entry.reason }}</p></li></ul><details><summary>Original result</summary><pre>{{ JSON.stringify(record, null, 2) }}</pre></details><details><summary>Original Finish response and reward receipt</summary><pre>{{ JSON.stringify({ initial_receipt, reward_receipt }, null, 2) }}</pre></details></section></template>
